-- Repair only the reviewed Parts Ordered read endpoint's permission seal and office boundary.
-- No stock, IMEI, issue, price, user or permission selections are changed.
begin;
set local statement_timeout='120s';
do $review$declare f record;stored text;actual text;prior text;begin
 if public.get_parts_order_tabs_version() is distinct from '20261107-parts-order-tabs-1' then raise exception 'The reviewed Parts Ordered tabs installation is required. No changes made.';end if;
 select p.*,l.lanname into strict f from pg_proc p join pg_language l on l.oid=p.prolang where p.oid='public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text)'::regprocedure;
 if md5(replace(replace(f.prosrc,chr(13)||chr(10),chr(10)),chr(13),chr(10))) not in ('d2adb48facea57f26c4b10a1e81e4a39','cf5a33ffbe1423323703628d38476c4a')
 or f.prosecdef is distinct from true or f.provolatile<>'s' or f.lanname<>'plpgsql' or f.prorettype<>'jsonb'::regtype
 or f.proconfig is distinct from array['search_path=pg_catalog, public']::text[]
 or f.proargnames is distinct from array['p_tab','p_filters','p_offset','p_limit','p_sort_key','p_sort_direction']::text[] then raise exception 'Parts Ordered query definition differs. Repair stopped.';end if;
 if to_regprocedure('greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text)') is not null then
  select p.*,l.lanname into strict f from pg_proc p join pg_language l on l.oid=p.prolang where p.oid='greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text)'::regprocedure;
  if md5(replace(replace(f.prosrc,chr(13)||chr(10),chr(10)),chr(13),chr(10)))<>'d2adb48facea57f26c4b10a1e81e4a39' or not f.prosecdef or f.provolatile<>'s' or f.lanname<>'plpgsql'
   or f.proconfig is distinct from array['search_path=pg_catalog, public']::text[] then raise exception 'Existing Parts Ordered private implementation differs. Repair stopped.';end if;
 end if;
 if exists(select 1 from greenloop_private.office_routines where to_regprocedure(identity)='public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text)'::regprocedure and implementation<>'greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text)') then raise exception 'Parts Ordered office registration differs. Repair stopped.';end if;
 if not exists(select 1 from greenloop_private.capability_rpc_rules where rpc_name='get_parts_order_tabs_v1'and rule='{"page":"parts","capability":"view","read":true}'::jsonb) then raise exception 'Parts Ordered permission rule differs. Repair stopped.';end if;
 select hash into strict stored from greenloop_private.page_capability_installation where identity='rules';
 select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)into actual from greenloop_private.capability_rpc_rules r;
 select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)into prior from greenloop_private.capability_rpc_rules r where rpc_name<>'get_parts_order_tabs_v1';
 if stored is distinct from actual and stored is distinct from prior then raise exception 'Other permission rules changed. This targeted repair will not reseal them.';end if;
end;$review$;
create or replace function greenloop_private.parts_order_tabs_queue(p_tab text default 'pending',p_filters jsonb default '{}',p_offset integer default 0,p_limit integer default 50,p_sort_key text default 'submitted_at',p_sort_direction text default 'desc')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare f date;t date;s text;st text;sc text;bn text;result jsonb;begin
 perform greenloop_private.pf_cap('parts','view');
 if p_tab is null or p_tab not in ('pending','issued','completed') or jsonb_typeof(p_filters)is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_filters)k where k not in ('_search','_from','_to','status','supplier_code','batch_number'))or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 50 or p_sort_key is null or p_sort_key not in ('submitted_at','imei','model','status','supplier_code','batch_number')or p_sort_direction is null or p_sort_direction not in ('asc','desc')then raise exception 'Select valid filters and sorting.'using errcode='22023';end if;
 if p_filters<>'{}'then perform greenloop_private.pf_cap('parts','search');end if;if p_sort_key<>'submitted_at' or p_sort_direction<>'desc'then perform greenloop_private.pf_cap('parts','sort');end if;
 f:=nullif(p_filters->>'_from','')::date;t:=nullif(p_filters->>'_to','')::date;s:=lower(btrim(coalesce(p_filters->>'_search','')));st:=nullif(p_filters->>'status','');sc:=nullif(p_filters->>'supplier_code','');bn:=nullif(p_filters->>'batch_number','');if f>t or length(s)>120 or length(sc)>120 or length(bn)>120 then raise exception 'Select valid dates or search.'using errcode='22023';end if;
 with latest as materialized(select distinct on(o.device_id) o.* from greenloop_private.parts_flow_orders o join public.jobs j on j.id=o.job_id and j.deleted_at is null join public.devices d on d.id=o.device_id and d.deleted_at is null where greenloop_private.ps_has_parts(o.id) order by o.device_id,o.submitted_at desc,o.id desc),base as materialized(select o.id order_id,o.revision,o.submitted_at,d.imei_1 imei,d.model,d.storage_gb,d.color,j.job_number,supplier.supplier_code,b.batch_number,b.invoice_number,coalesce(b.received_at,j.received_at)stock_received_at,greenloop_private.ps_status(o.id)status,coalesce((select s.assigned_technician_name from public.job_work_order_steps s where s.id=o.step_id),'Unassigned')technician_name,(select count(*)from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and r.status<>'cancelled')parts_count from latest o join public.jobs j on j.id=o.job_id and j.deleted_at is null join public.devices d on d.id=o.device_id and d.deleted_at is null left join public.suppliers supplier on supplier.id=j.supplier_id left join public.receiving_batches b on b.id=j.receiving_batch_id where greenloop_private.ps_has_parts(o.id)),filtered as materialized(select * from base where(f is null or(submitted_at at time zone 'Asia/Dubai')::date>=f)and(t is null or(submitted_at at time zone 'Asia/Dubai')::date<=t)and(s=''or strpos(lower(concat_ws(' ',imei,model,storage_gb,color,job_number,technician_name,supplier_code,batch_number,invoice_number)),s)>0)and(st is null or status=st)and(sc is null or supplier_code=sc)and(bn is null or batch_number=bn)),grouped as materialized(select *,case when status='Completed' then 'completed' when status='Issued' then 'issued' else 'pending' end order_tab from filtered),q as materialized(select * from grouped where order_tab=p_tab),page as(select *from q order by case when p_sort_key='submitted_at'and p_sort_direction='asc'then submitted_at end asc,case when p_sort_key='submitted_at'and p_sort_direction='desc'then submitted_at end desc,case when p_sort_direction='asc'then case p_sort_key when 'imei'then imei when 'model'then model when 'status'then status when 'supplier_code'then supplier_code when 'batch_number'then batch_number end end asc,case when p_sort_direction='desc'then case p_sort_key when 'imei'then imei when 'model'then model when 'status'then status when 'supplier_code'then supplier_code when 'batch_number'then batch_number end end desc,order_id offset p_offset limit p_limit)
 select jsonb_build_object('total',(select count(*)from q),'counts',(select jsonb_build_object('pending',count(*)filter(where order_tab='pending'),'issued',count(*)filter(where order_tab='issued'),'completed',count(*)filter(where order_tab='completed'))from grouped),'rows',coalesce((select jsonb_agg(to_jsonb(p))from page p),'[]'),'facets',jsonb_build_object('status',(select coalesce(jsonb_agg(distinct status),'[]')from base),'supplier_code',(select coalesce(jsonb_agg(distinct supplier_code order by supplier_code),'[]')from base where supplier_code is not null),'batch_number',(select coalesce(jsonb_agg(distinct batch_number order by batch_number),'[]')from base where batch_number is not null)))into result;return result;
end;$$;
revoke all on function greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text) from public,anon,authenticated;
create or replace function public.get_parts_order_tabs_v1(p_tab text default 'pending',p_filters jsonb default '{}',p_offset integer default 0,p_limit integer default 50,p_sort_key text default 'submitted_at',p_sort_direction text default 'desc')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$begin perform greenloop_private.require_office_network();return greenloop_private.parts_order_tabs_queue(p_tab,p_filters,p_offset,p_limit,p_sort_key,p_sort_direction);end;$$;

revoke all on function public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text) from public,anon;
grant execute on function public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text) to authenticated;
insert into greenloop_private.office_routines(identity,implementation,original_hash,wrapped_hash)
values('public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text)','greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text)',md5(pg_get_functiondef('greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text)'::regprocedure)),md5(pg_get_functiondef('public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text)'::regprocedure)))
on conflict(identity)do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r)where identity='rules';
alter table greenloop_private.parts_order_tabs_installation enable row level security;
update greenloop_private.parts_order_tabs_installation set hash=md5(pg_get_functiondef('public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text)'::regprocedure))where identity='public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text)';
create table if not exists greenloop_private.parts_tabs_boundary_installation(identity text primary key,hash text not null);
alter table greenloop_private.parts_tabs_boundary_installation enable row level security;
revoke all on greenloop_private.parts_tabs_boundary_installation from public,anon,authenticated;
create or replace function public.get_parts_tabs_boundary_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$
 select case when public.get_parts_order_tabs_version()='20261107-parts-order-tabs-1'
 and exists(select 1 from greenloop_private.page_capability_installation where identity='rules'and hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r))
 and(select count(*)=3 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.parts_tabs_boundary_installation)
 and exists(select 1 from greenloop_private.office_routines where identity='public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text)'and implementation='greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text)'and original_hash=md5(pg_get_functiondef('greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text)'::regprocedure))and wrapped_hash=md5(pg_get_functiondef('public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text)'::regprocedure)))
 and not has_function_privilege('anon','greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text)','execute') and not has_function_privilege('authenticated','greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text)','execute')
 and not exists(select 1 from pg_class where oid in('greenloop_private.parts_tabs_boundary_installation'::regclass,'greenloop_private.parts_order_tabs_installation'::regclass)and(not relrowsecurity or has_table_privilege('anon',oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')or has_table_privilege('authenticated',oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')))
 then '20261107-parts-tabs-boundary-1' end
$$;
revoke all on function public.get_parts_tabs_boundary_version()from public;
grant execute on function public.get_parts_tabs_boundary_version()to anon,authenticated;
insert into greenloop_private.parts_tabs_boundary_installation select x,md5(pg_get_functiondef(x::regprocedure))from unnest(array['public.get_parts_order_tabs_v1(text,jsonb,integer,integer,text,text)','greenloop_private.parts_order_tabs_queue(text,jsonb,integer,integer,text,text)','public.get_parts_tabs_boundary_version()'])x on conflict(identity)do update set hash=excluded.hash;
do $$begin if public.get_parts_tabs_boundary_version()is distinct from '20261107-parts-tabs-boundary-1'
 or public.get_page_capabilities_version()is distinct from '20261016-page-capabilities-1'
 or public.get_office_access_version()is distinct from '20261024-office-access-1'
 or public.get_complete_stock_lists_version()is distinct from '20261105-complete-stock-lists-1'
 then raise exception 'Parts boundary repair did not restore integrity. All repair changes rolled back.';end if;end$$;
notify pgrst,'reload schema';
commit;
select public.get_parts_tabs_boundary_version()as installed_parts_tabs_boundary_version;
